sys_script_include.script:
var EventUtilsCS = Class.create();
EventUtilsCS.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getEventDetails: function() {
		var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new EventUtils().getEventDetails(_eventId));
    },

    isEventVIP: function() {
		var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new EventUtils().isEventVIP(_eventId));
    },

    calculateRemainingBudget: function() {
		var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new EventUtils().calculateRemainingBudget(_eventId));
    },

    getEventTasks: function() {
		var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new EventUtils().getEventTasks(_eventId));
    },

    getEventAttendees: function() {
		var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new EventUtils().getEventAttendees(_eventId));
    },

    getEventVendors: function() {
		var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new EventUtils().getEventVendors(_eventId));
    },

    getEventBudgetDetails: function() {
		var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new EventUtils().getEventBudgetDetails(_eventId));
    },

    getEventFeedback: function() {
		var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new EventUtils().getEventFeedback(_eventId));
    },

    type: 'EventUtilsCS'
});
